CREATE COLUMN TABLE "TEST_AP"."TRS1" ("AbsEntry" INTEGER CS_INT NOT NULL , "ObjType" NVARCHAR(20), "LineID" INTEGER CS_INT NOT NULL , "ApDocType" NVARCHAR(20) NOT NULL , "ApDocEntry" INTEGER CS_INT NOT NULL , "ApDocOrdNo" INTEGER CS_INT DEFAULT -1 NOT NULL , "ApDocAdRef" INTEGER CS_INT DEFAULT -1, "MeansType" INTEGER CS_INT DEFAULT -1 NOT NULL , "PayLineID" INTEGER CS_INT DEFAULT -1 NOT NULL , "PayDocType" INTEGER CS_INT DEFAULT -1 NOT NULL , "PayDocEntr" INTEGER CS_INT DEFAULT -1 NOT NULL , PRIMARY KEY ("AbsEntry", "LineID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "TRS1_SECONDARY" ON "TEST_AP"."TRS1" ( "AbsEntry" ASC, "ApDocType" ASC, "ApDocEntry" ASC, "ApDocOrdNo" ASC, "MeansType" ASC, "PayLineID" ASC, "PayDocType" ASC, "PayDocEntr" ASC )